			$args = [
				'post_type'      => 'news',
				'post_status'    => 'publish',
				'orderby'        => 'date',
				'order'          => 'DESC',
				'posts_per_page' => 3,
				'meta_query'       => array(
					array(
						'key'     => 'starlink_news',
						'value'   => 'starlink', // for live change to starlink
						'compare' => 'LIKE'
					)
				),
				'tax_query' => [
					[
						'taxonomy' => 'news_type',
						'field' => 'slug',
						'terms' => 'insights'
					]
				]
			];

            $query = new WP_Query($args);
			if ($query->have_posts()) :
                get_template_part(
                    'template-parts/modules/featured-news',
                    null,
                    array(
                        'heading' => $news['heading'],
                        'query' => $query
                    )
                );
            endif;
			?>
<?php endif; ?>

